<?php
use App\Actions\Donations\SaveDonation; use App\DonationPaymentMethod; use App\Models\Donation; use App\Models\DonationCampaign; use App\Models\DonationCategory; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Gate; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('Edit Donation')] class extends Component { public Donation $donation; public string $categoryId=''; public string $campaignId=''; public string $amount=''; public string $currency=''; public string $method=''; public string $donatedAt=''; public string $providerReference=''; public string $transactionReference=''; public string $notes=''; public string $internalNotes=''; public function mount():void{Gate::authorize('update',$this->donation);$this->categoryId=(string)$this->donation->donation_category_id;$this->campaignId=(string)($this->donation->donation_campaign_id??'');$this->amount=$this->donation->amount;$this->currency=$this->donation->currency;$this->method=$this->donation->payment_method->value;$this->donatedAt=$this->donation->donated_at->format('Y-m-d\TH:i');$this->providerReference=$this->donation->provider_reference??'';$this->transactionReference=$this->donation->transaction_reference??'';$this->notes=$this->donation->notes??'';$this->internalNotes=$this->donation->internal_notes??'';} public function save(SaveDonation $save):void{$data=$this->validate(['categoryId'=>['required','exists:donation_categories,id'],'campaignId'=>['nullable','exists:donation_campaigns,id'],'amount'=>['required','numeric','gt:0'],'currency'=>['required','alpha','size:3'],'method'=>['required',Rule::enum(DonationPaymentMethod::class)],'donatedAt'=>['required','date'],'providerReference'=>['nullable','max:255',Rule::unique('donations','provider_reference')->ignore($this->donation)],'transactionReference'=>['nullable','max:255'],'notes'=>['nullable','max:5000'],'internalNotes'=>['nullable','max:5000']]);$saved=$save->handle(Auth::user(),['donation_category_id'=>$data['categoryId'],'donation_campaign_id'=>$data['campaignId']?:null,'amount'=>$data['amount'],'currency'=>strtoupper($data['currency']),'payment_method'=>$data['method'],'donated_at'=>$data['donatedAt'],'provider_reference'=>$data['providerReference']?:null,'transaction_reference'=>$data['transactionReference']?:null,'notes'=>$data['notes']?:null,'internal_notes'=>$data['internalNotes']?:null],$this->donation);session()->flash('success',__('Donation updated.'));$this->redirectRoute('donations.show',$saved,navigate:true);} public function categories(){return DonationCategory::orderBy('name')->get();} public function campaigns(){return DonationCampaign::orderBy('name')->get();} }; ?>
<div class="mx-auto w-full max-w-4xl space-y-6"><x-admin.page-header :title="__('Edit donation')" :description="$donation->reference" :eyebrow="__('Giving management')"/><form wire:submit="save" class="space-y-5 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><div class="grid gap-4 sm:grid-cols-2"><flux:select wire:model="categoryId" :label="__('Category')">@foreach($this->categories() as $x)<flux:select.option :value="$x->id">{{$x->name}}</flux:select.option>@endforeach</flux:select><flux:select wire:model="campaignId" :label="__('Campaign')"><flux:select.option value="">{{__('None')}}</flux:select.option>@foreach($this->campaigns() as $x)<flux:select.option :value="$x->id">{{$x->name}}</flux:select.option>@endforeach</flux:select><flux:input wire:model="amount" type="number" step="0.01" :label="__('Amount')"/><flux:input wire:model="currency" :label="__('Currency')"/><flux:select wire:model="method" :label="__('Payment method')">@foreach(DonationPaymentMethod::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:input wire:model="donatedAt" type="datetime-local" :label="__('Donation date')"/><flux:input wire:model="providerReference" :label="__('Provider reference')"/><flux:input wire:model="transactionReference" :label="__('Transaction reference')"/></div><flux:textarea wire:model="notes" :label="__('Public notes')"/><flux:textarea wire:model="internalNotes" :label="__('Internal notes')"/><div class="flex justify-end gap-3"><flux:button :href="route('donations.show',$donation)" wire:navigate>{{__('Cancel')}}</flux:button><flux:button type="submit" variant="primary" wire:loading.attr="disabled" wire:target="save">{{__('Save changes')}}</flux:button></div></form></div>
